package com.intermarche.backoffice.engine.fieldops;
import static com.intermarche.backoffice.domain.fieldops.FieldEntityIds.id;
import com.intermarche.backoffice.domain.shipping.*;import com.intermarche.backoffice.domain.stock.*;import com.intermarche.backoffice.domain.store.*;import com.intermarche.backoffice.domain.executing.*;import com.intermarche.backoffice.client.PickingExecution;import com.intermarche.backoffice.domain.util.DateTimeProvider;import com.intermarche.backoffice.engine.stock.*;import com.intermarche.backoffice.engine.operator.OperatorFailure;
import jakarta.enterprise.context.ApplicationScoped;import jakarta.inject.Inject;import jakarta.persistence.EntityManager;import jakarta.transaction.Transactional;import jakarta.ws.rs.*;import java.math.BigDecimal;import java.util.*;
/** Converts logical parcel allocations into exclusive physical custody without creating or consuming goods. */
@ApplicationScoped @Transactional
public class ParcelPhysicalService {
 @Inject EntityManager em;@Inject StockTraceLedger ledger;@Inject PickedStockCoordinator custody;@Inject FieldOperationsService field;
 private void history(Parcel p,String action,String reason){var h=new LogisticsHistory();h.store=p.store;h.subjectType="PARCEL";h.subjectId=p.id;h.action=action;h.actor=field.actor();h.reason=reason;h.snapshot=field.encode(Map.of("materialized",p.materialized,"address",p.currentAddress==null?"":p.currentAddress));h.persist();}
 private Map<String,Object> trace(PickedStockAllocation a){var row=new LinkedHashMap<String,Object>();row.put("allocationId",a.id);row.put("quantity",a.quantity);row.put("lotId",a.holding.lot==null?null:id(a.holding.lot));row.put("lot",a.holding.lot==null?null:a.holding.lot.code);row.put("serialId",a.holding.serial==null?null:id(a.holding.serial));row.put("serial",a.holding.serial==null?null:a.holding.serial.code);row.put("quality",a.holding.quality);return row;}
 private ParcelStockLocation address(Parcel p,StockSegment source,Building building){var location=ParcelStockLocation.<ParcelStockLocation>find("parcel=?1 and product=?2 and id in (select l.id from Building b join b.locations l where b=?3)",p,source.account.product,building).firstResult();if(location==null){location=new ParcelStockLocation();location.parcel=p;location.product=source.account.product;location.area="COLIS";location.aisle="COLIS";location.unit="COLIS";location.elevation="1";location.position="1";location.locationCode="COL-"+p.id+"-"+id(source.account.product)+"-"+building.id;location.persistAndFlush();building.locations.add(location);}return location;}
 public void materialize(Parcel p,String currentAddress){
  if(p.materialized){p.currentAddress=currentAddress;p.currentBuffer=null;return;}
  if(!"CLOSED".equals(p.state))throw new OperatorFailure(409,"PARCEL_NOT_CLOSED","Fermez et contrôlez le colis avant de le charger.");
  var contents=ParcelContent.<ParcelContent>list("select c from ParcelContent c join fetch c.pickedItem i join fetch i.product left join fetch i.loadedTote where c.parcel=?1 order by c.id",p);if(contents.isEmpty())throw new BadRequestException("Un colis vide ne peut pas être chargé");
  var ids=contents.stream().map(c->id(c.pickedItem)).toList();var stateMap=new HashMap<Long,PickedStockState>();for(var state:PickedStockState.<PickedStockState>list("store=?1 and itemId in ?2",p.store,ids))stateMap.put(state.itemId,state);
  // Unknown imported custody is materialized only when its actual source balance covers it.
  for(var c:contents){var state=stateMap.get(id(c.pickedItem));if(state==null)throw new OperatorFailure(409,"PARCEL_CUSTODY_UNKNOWN","Contrôlez la provenance physique avant de charger ce colis.");if(state.legacyQuantity.signum()>0&&!custody.materializeLegacy(state))throw new OperatorFailure(409,"PARCEL_CUSTODY_UNKNOWN","Le stock source ne couvre pas cette préparation historique. Faites contrôler l’inventaire.");}
  var byState=new HashMap<Long,List<PickedStockAllocation>>();for(var allocation:PickedStockAllocation.<PickedStockAllocation>list("select a from PickedStockAllocation a join fetch a.holding h left join fetch h.lot left join fetch h.serial join fetch h.account where a.state in ?1 and a.shipped=false and a.quantity>0 order by a.id",stateMap.values()))byState.computeIfAbsent(id(allocation.state),ignored->new ArrayList<>()).add(allocation);
  var ownerMap=new HashMap<Long,PickingExecution>();for(Object[] row:em.createQuery("select i.id,e from PickingExecution e join e.itemsToPick i where i.id in ?1",Object[].class).setParameter(1,ids).getResultList())ownerMap.put((Long)row[0],(PickingExecution)row[1]);
  Building commonBuilding=null;
  for(var c:contents){var item=c.pickedItem;if(item.loadedTote==null||item.status!=PickedItem.PickStatus.PICKED||c.sourceQuantity.compareTo(item.quantity)!=0||!Objects.equals(c.sourceToteId,id(item.loadedTote)))throw new OperatorFailure(409,"PARCEL_CONTENT_CHANGED","Le contenu a changé depuis le contrôle : rouvrez et contrôlez de nouveau le colis.");c.sourceToteCode=item.loadedTote.tote.code;c.sourceAddress=String.join(" → ",java.util.stream.Stream.of(item.loadedTote.buffer==null?null:item.loadedTote.buffer.bufferCode,item.loadedTote.cabinet==null?null:item.loadedTote.cabinet.code,item.loadedTote.cellRow==null?null:item.loadedTote.cellRow+"/"+item.loadedTote.cellColumn).filter(Objects::nonNull).toList());var state=stateMap.get(item.id);var allocations=byState.getOrDefault(state.id,List.of());BigDecimal traced=allocations.stream().map(a->a.quantity).reduce(BigDecimal.ZERO,BigDecimal::add);if(traced.compareTo(item.quantity)!=0)throw new OperatorFailure(409,"PARCEL_TRACE_CHANGED","La traçabilité ne couvre plus la quantité préparée.");
   var wanted=new LinkedHashMap<Long,BigDecimal>();for(var raw:field.decode(c.traceSnapshot,List.class)){var row=(Map<?,?>)raw;if(row.get("allocationId")!=null)wanted.put(((Number)row.get("allocationId")).longValue(),new BigDecimal(row.get("quantity").toString()));}
   if(wanted.isEmpty()){BigDecimal remaining=c.quantity;for(var allocation:allocations){BigDecimal take=remaining.min(allocation.quantity);if(take.signum()>0)wanted.put(allocation.id,take);remaining=remaining.subtract(take);if(remaining.signum()==0)break;}if(remaining.signum()>0)throw new BadRequestException("Traçabilité historique insuffisante");}
   PickedItem enclosed=item;PickedStockState enclosedState=state;Long oldItemId=item.id;
   if(c.quantity.compareTo(item.quantity)<0){enclosed=new PickedItem();enclosed.product=item.product;enclosed.lotLine=item.lotLine;enclosed.sourceLocation=item.sourceLocation;enclosed.quantity=c.quantity;enclosed.status=PickedItem.PickStatus.PICKED;enclosed.persistAndFlush();var owner=ownerMap.get(oldItemId);if(owner!=null)owner.itemsToPick.add(enclosed);item.quantity=item.quantity.subtract(c.quantity);enclosedState=new PickedStockState();enclosedState.store=p.store;enclosedState.itemId=enclosed.id;enclosedState.lotLineId=id(enclosed.lotLine);enclosedState.product=enclosed.product;enclosedState.persistAndFlush();c.pickedItem=enclosed;
    var others=ParcelContent.<ParcelContent>list("pickedItem=?1 and parcel<>?2 and parcel.state<>'CANCELLED'",item,p);for(var other:others){other.sourceQuantity=item.quantity;other.parcel.revisionNumber++;history(other.parcel,"SOURCE_SPLIT","Séparation physique d’un autre colis ; la quantité contrôlée de ce colis est conservée.");}
   }
   var captured=new ArrayList<Map<String,Object>>();for(var part:wanted.entrySet()){var origin=allocations.stream().filter(a->a.id.equals(part.getKey())).findFirst().orElseThrow(()->new OperatorFailure(409,"PARCEL_TRACE_CHANGED","Une allocation du colis a changé"));if(origin.quantity.compareTo(part.getValue())<0)throw new OperatorFailure(409,"PARCEL_TRACE_CHANGED","La quantité du lot a changé");StockQualityRules.requireSegment(origin.holding,"SHIPPING");var buildings=BaseLocation.findBuildingsByLocations(List.of(origin.holding.location));if(buildings.size()!=1)throw new BadRequestException("Adresse source du colis ambiguë");var building=buildings.getFirst();if(commonBuilding!=null&&!id(commonBuilding).equals(id(building)))throw new BadRequestException("Rassemblez les bacs dans le même bâtiment avant de charger un colis commun");commonBuilding=building;var location=address(p,origin.holding,building);var target=ledger.segment(origin.holding.account,location,null,origin.holding.lot,origin.holding.serial,origin.holding.quality);target.receivedAt=origin.holding.receivedAt;ledger.move(origin.holding,target,part.getValue(),"parcel:"+p.id+":materialize",c.id+":"+origin.id,"PARCEL_PACKING");origin.quantity=origin.quantity.subtract(part.getValue());var a=new PickedStockAllocation();a.state=enclosedState;a.origin=origin.origin;a.holding=target;a.quantity=part.getValue();a.persistAndFlush();captured.add(trace(a));}
   enclosed.loadedTote=null;c.sourceQuantity=enclosed.quantity;c.traceSnapshot=field.encode(captured);
  }
  p.materialized=true;p.currentBuffer=null;p.currentAddress=currentAddress;em.flush();history(p,"MATERIALIZED","Marchandises placées dans le colis identifié ; quantités retirées des bacs sources, sans départ de stock.");
 }
 public void putInBuffer(Parcel p,Buffer buffer){if(!p.materialized)throw new BadRequestException("Colis non matérialisé");if(buffer==null||buffer.building==null||!Objects.equals(id(Building.findStoreByBuildingId(id(buffer.building))),id(p.store)))throw new BadRequestException("Buffer hors du magasin");if(!buffer.active)throw new BadRequestException("Ce buffer est désactivé");for(var c:ParcelContent.<ParcelContent>list("parcel",p)){var zone=c.pickedItem.product.temperatureZone;if(buffer.getCapacityForZone(zone==TemperatureZone.HOUSEHOLD?TemperatureZone.AMBIENT:zone)<=0)throw new BadRequestException("Ce buffer ne prend pas en charge le conditionnement du colis");}var allocations=PickedStockAllocation.<PickedStockAllocation>list("select a from PickedStockAllocation a join fetch a.holding where a.state.itemId in (select c.pickedItem.id from ParcelContent c where c.parcel=?1) and a.shipped=false and a.quantity>0",p);for(var a:allocations){var target=ledger.segment(a.holding.account,address(p,a.holding,buffer.building),null,a.holding.lot,a.holding.serial,a.holding.quality);target.receivedAt=a.holding.receivedAt;ledger.move(a.holding,target,a.quantity,"parcel:"+p.id+":buffer:"+p.revisionNumber,"allocation:"+a.id,"PARCEL_MOVE");a.holding=target;}p.currentBuffer=buffer;p.currentAddress=buffer.bufferCode;history(p,"UNLOADED","Colis déchargé et déposé dans le buffer "+buffer.bufferCode);}
 public LoadedTote resolveUnpackTarget(Parcel p,Long targetToteId){if(p.materialized&&(!"CLOSED".equals(p.state)||p.currentBuffer==null))throw new OperatorFailure(409,"PARCEL_UNLOAD_REQUIRED","Déchargez le colis dans un buffer avant de le rouvrir.");var contents=ParcelContent.<ParcelContent>list("parcel",p);LoadedTote target=targetToteId==null?LoadedTote.findById(contents.getFirst().sourceToteId):LoadedTote.findById(targetToteId);if(target==null||target.status!=LoadedTote.Status.IN_USE||!id(target.tote.store).equals(id(p.store))||target.loadingDeparture!=null)throw new BadRequestException("Choisissez un bac actif du magasin pour déballer les produits");SupportLayoutService.requireWritable(target);for(var c:contents)if(!target.tote.isUsageAllowed(c.pickedItem.product.temperatureZone)||target.storageType!=c.pickedItem.product.temperatureZone)throw new BadRequestException("Le bac choisi est incompatible avec le conditionnement");var handlingProducts=new ArrayList<com.intermarche.backoffice.domain.order.Product>();for(var item:PickedItem.<PickedItem>list("loadedTote=?1 and status=?2 and quantity>0",target,PickedItem.PickStatus.PICKED))handlingProducts.add(item.product);for(var c:contents){for(var other:handlingProducts)com.intermarche.backoffice.engine.stock.ProductHandlingRules.requireCompatible(p.store,c.pickedItem.product,other);handlingProducts.add(c.pickedItem.product);}var estimateItems=new ArrayList<SupportLoadEstimate.Item>();for(var item:PickedItem.<PickedItem>list("loadedTote=?1 and status=?2 and quantity>0",target,PickedItem.PickStatus.PICKED))estimateItems.add(new SupportLoadEstimate.Item(item.product.productType.name(),item.quantity,item.product.referenceWeight,item.product.referenceVolume));for(var c:contents)estimateItems.add(new SupportLoadEstimate.Item(c.pickedItem.product.productType.name(),c.quantity,c.pickedItem.product.referenceWeight,c.pickedItem.product.referenceVolume));var estimate=SupportLoadEstimate.estimate(estimateItems);var limits=OperationalPolicyVersions.active(p.store,"SupportConstraints");var support=com.intermarche.backoffice.domain.fieldops.PhysicalSupport.<com.intermarche.backoffice.domain.fieldops.PhysicalSupport>find("tote",target.tote).firstResult();var capacity=target.tote.volume;if(support!=null&&support.type.maxVolumeLiters!=null)capacity=capacity.min(support.type.maxVolumeLiters);capacity=capacity.multiply(BigDecimal.valueOf(limits.path("maximumFillPercent").asInt(100))).divide(BigDecimal.valueOf(100));BigDecimal maxKg=support==null?null:support.type.maxWeightKg;if(limits.hasNonNull("maximumWeightKg"))maxKg=maxKg==null?limits.path("maximumWeightKg").decimalValue():maxKg.min(limits.path("maximumWeightKg").decimalValue());if(estimate.liters().compareTo(capacity)>0||maxKg!=null&&estimate.kg().compareTo(maxKg)>0)throw new OperatorFailure(409,"SUPPORT_CAPACITY_EXCEEDED","Les produits dépassent la capacité autorisée du bac. Choisissez un autre support.");return target;}
 public void unpack(Parcel p,Long targetToteId){if(!p.materialized)return;var target=resolveUnpackTarget(p,targetToteId);var contents=ParcelContent.<ParcelContent>list("parcel",p);var ids=contents.stream().map(c->id(c.pickedItem)).toList();for(var a:PickedStockAllocation.<PickedStockAllocation>list("select a from PickedStockAllocation a join fetch a.holding where a.state.itemId in ?1 and a.shipped=false and a.quantity>0",ids)){var destination=ledger.holding(a.holding,target);ledger.move(a.holding,destination,a.quantity,"parcel:"+p.id+":unpack:"+p.revisionNumber,"allocation:"+a.id,"PARCEL_UNPACKING");a.holding=destination;}for(var c:contents){c.pickedItem.loadedTote=target;c.sourceToteId=target.id;c.sourceToteCode=target.tote.code;c.sourceAddress=target.buffer==null?null:target.buffer.bufferCode;c.sourceQuantity=c.pickedItem.quantity;}p.materialized=false;p.currentBuffer=null;p.currentAddress=null;history(p,"UNPACKED","Produits déballés dans le bac "+target.tote.code+" avant correction habilitée");}
}
